// As funções devolvem o valor: nenhuma pode imprimir.
function semImprimir(corpo) {
  const original = console.log;
  let chamadas = 0;
  console.log = () => { chamadas++; };
  try { corpo(); } finally { console.log = original; }
  return chamadas;
}

